users = {
    'u001': {'name': 'Alice', 'scores': [90, 85, 92]},
    'u002': {'name': 'Bob'},
    'u003': {'name': 'Charlie', 'scores': [78, 88]}
}
for uid, info in users.items():
    name = info.get('name', '未知')
    scores = info.get('scores', [])
    if scores:
        avg = sum(scores) / len(scores)
        print(f'{name}: 平均分 {avg:.1f}（{len(scores)}科）')
    else:
        print(f'{name}: 暂无成绩')

